resource "aws_iam_role_policy" "agent_runtime_role_policy" {
  role   = aws_iam_role.agent_runtime_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BedrockModelInvocation"
        Effect = "Allow"
        Action = [
          "bedrock:InvokeModel",
          "bedrock:InvokeModelWithResponseStream"
        ]
        "Resource": "*"
      },
      {
        Sid    = "CodeInterpreterAccess"
        Effect = "Allow"
        Action = [
          "bedrock-agentcore:InvokeCodeInterpreter",
          "bedrock-agentcore:StartCodeInterpreterSession",
          "bedrock-agentcore:StopCodeInterpreterSession"
        ]
        "Resource": "*"
      },
      {
        Sid    = "KnowledgeBaseAccess"
        Effect = "Allow"
        Action = [
          "bedrock:Retrieve",
          "bedrock:RetrieveAndGenerate"
        ]
        "Resource": aws_bedrockagent_knowledge_base.kb.arn
      }
    ]
  })
}

resource "aws_iam_user" "starting_user" {
  name = "sandy_${var.cgid}"
}

resource "aws_iam_policy" "starting_user_bedrock_policy" {
  name = "agent_access_policy_${var.cgid}"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid    = "BedrockReadOnly"
        Effect = "Allow"
        Action = [
          "bedrock:Get*",
          "bedrock:List*",
          "bedrock-agentcore:Get*",
          "bedrock-agentcore:List*"
        ],
        Resource = "*"
      },
      {
        Sid    = "CodeInterpreterManagement"
        Effect = "Allow",
        Action = [
          "bedrock-agentcore:*CodeInterpreter*"
        ],
        Resource = "*"
      },
      {
        Sid    = "CodeInterpreterRoleManagement"
        Effect = "Allow",
        Action = [
          "iam:PassRole"
        ],
        Resource = "arn:aws:iam::${data.aws_caller_identity.aws-account-id.account_id}:role/agentcore_*"
      }
    ]
  })
}

resource "aws_elastic_beanstalk_environment" "eb_env" {
  name                = replace("${var.cgid}-env", "_", "-")
  application         = aws_elastic_beanstalk_application.eb_app.name
  # Dynamically use the latest Python solution stack found by the data source
  solution_stack_name = data.aws_elastic_beanstalk_solution_stack.python_stack.name

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "SECONDARY_ACCESS_KEY"
    value     = aws_iam_access_key.secondary_key.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "SECONDARY_SECRET_KEY"
    value     = aws_iam_access_key.secondary_key.secret
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }
  # Launch this in the CG VPC
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.vpc.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = aws_subnet.subnet.id
  }

